/* From Uiverse.io by Spacious74  - Tags: active, radio, menu */
.__UIV_SCOPE__ .radio-inputs {
  position: relative;
  display: flex;
  border-radius: 0.5rem;
  background-color: #70c489;
  box-sizing: border-box;
  font-size: 14px;
  width: 90%;
  padding: 1rem 1rem 0 1rem;
}

.__UIV_SCOPE__ .radio-inputs .radio input {
  display: none;
}

.__UIV_SCOPE__ .radio-inputs .radio .name {
  display: flex;
  cursor: pointer;
  align-items: center;
  justify-content: center;
  border-top-left-radius: 0.5rem;
  border-top-right-radius: 0.5rem;
  border: none;
  padding: 0.5rem 0.8rem;
  color: ;
  transition: all 0.15s ease-in-out;
  position: relative;
}

.__UIV_SCOPE__ .radio-inputs .radio input:checked + .name {
  background-color: #e8e8e8;
  font-weight: 600;
}
.__UIV_SCOPE__ .radio-inputs .radio input + .name:hover {
  color: #fff;
}
.__UIV_SCOPE__ .radio-inputs .radio input:checked + .name:hover {
  color: #1d1d29;
}

.__UIV_SCOPE__ .radio-inputs .radio input:checked + .name::after,
.__UIV_SCOPE__ .radio-inputs .radio input:checked + .name::before {
  content: "";
  position: absolute;
  width: 10px;
  height: 10px;
  background-color: #70c489;
  bottom: 0;
}

.__UIV_SCOPE__ .radio-inputs .radio input:checked + .name::after {
  right: -10px;
  border-bottom-left-radius: 300px;
  box-shadow: -3px 3px 0px 3px #e8e8e8;
}
.__UIV_SCOPE__ .radio-inputs .radio input:checked + .name::before {
  left: -10px;
  border-bottom-right-radius: 300px;
  box-shadow: 3px 3px 0px 3px #e8e8e8;
}
